import json, numpy as np
from loss.eager_ce import per_position_terms
records=[json.loads(l) for l in open('vectors/eval_records.jsonl')]
metrics=json.load(open('vectors/recorded_metrics.json'))
errors={}
for r in records:
 y=np.array(r['labels']); valid=np.flatnonzero(y!=-100); n=len(y)
 candidates={'all':np.arange(n),'supervised':valid,'hull':np.arange(valid[0],valid[-1]+1) if len(valid) else np.array([],dtype=int),'through_last':np.arange(valid[-1]+1) if len(valid) else np.array([],dtype=int),'leading_supervised':np.arange(np.flatnonzero(y==-100)[0] if np.any(y==-100) else n)}
 t=per_position_terms(r['logits'],y,r['label_smoothing'])
 for k,ix in candidates.items():
  value=float(t[ix].sum())/(len(ix) if r['reduction']=='mean' and len(ix) else 1)
  err=abs(value-metrics[r['id']])
  errors.setdefault((r['count_policy'],k),[]).append(err)
for k,errs in errors.items():
 print(k,'matches',sum(e<1e-10 for e in errs),'of',len(errs),'max_abs',max(errs))
PY","max_output_tokens":4000}));

